const newBlock = `def find_saved_keyframe_prompt(state: dict[str, object]) -> dict[str, object] | None:
    prompt_dir = ANNOTATION_ROOT / "prompts" / str(state["sequence_id"])
    for prompt_path in sorted(prompt_dir.glob("frame_*.json")):
        if prompt_path.name.endswith("_no_device.json"):
            continue
        try:
            payload = json.loads(prompt_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        box = payload.get("box")
        frame_index = int(payload.get("frame_index", -1))
        if isinstance(box, list) and len(box) == 4 and 0 <= frame_index < len(state["frame_paths"]):
            return payload
    return None


def run_sequence_propagation(sequence_state: dict[str, object], action: str = "auto_annotate_5_frames"):
    state = dict(sequence_state)
    keyframe_prompt = find_saved_keyframe_prompt(state)
    if keyframe_prompt is None:
        state["status"] = "无法自动标注：当前短序列没有已保存的关键帧设备框。"
        return compose_outputs(state)
    keyframe_index = int(keyframe_prompt["frame_index"])
    keyframe_box = [float(value) for value in keyframe_prompt["box"]]
    positive_points = keyframe_prompt.get("positive_points", [])
    negative_points = keyframe_prompt.get("negative_points", [])

    annotator = SAM2SequenceAnnotator(
        SAM2_CONFIG,
        str(SAM2_CHECKPOINT),
        device="cuda" if torch.cuda.is_available() else "cpu",
    )
    annotator.load_sequence(Path(state["sequence_dir"]))
    autocast = torch.autocast("cuda", dtype=torch.bfloat16) if torch.cuda.is_available() else torch.no_grad()
    with torch.inference_mode(), autocast:
        annotator.set_keyframe_box(keyframe_index, keyframe_box)
        for x, y in positive_points:
            annotator.add_point(float(x), float(y), True, frame_index=keyframe_index)
        for x, y in negative_points:
            annotator.add_point(float(x), float(y), False, frame_index=keyframe_index)
        propagated: dict[int, np.ndarray] = {}
        for reverse in (False, True):
            for out_frame_idx, out_obj_ids, out_mask_logits in annotator.propagate(
                start_frame_idx=keyframe_index,
                reverse=reverse,
            ):
                obj_ids = [int(value) for value in out_obj_ids]
                if 1 not in obj_ids:
                    continue
                propagated[int(out_frame_idx)] = logit_to_mask(out_mask_logits[obj_ids.index(1)])

    existing_rows = read_sequence_review(str(state["sequence_id"]))
    existing_by_index = {int(row["frame_index"]): normalize_review_row(row) for row in existing_rows}
    rows: list[dict[str, object]] = []
    previous_mask = None
    previous_bbox = None
    for idx, frame_path in enumerate(state["frame_paths"]):
        existing = existing_by_index.get(idx)
        if existing is not None and is_protected_review_row(existing):
            row = existing
            preview_path = str(row["preview_path"])
            mask_path = str(row["device_mask_visible_path"])
        else:
            image = load_rgb_image(Path(frame_path))
            if no_device_marker_exists(state, idx):
                row, preview_path, mask_path = save_phase1b_outputs(
                    state,
                    idx,
                    image,
                    None,
                    "no_device",
                    reason="marked_no_device",
                )
            elif idx in propagated:
                row, preview_path, mask_path = save_phase1b_outputs(
                    state,
                    idx,
                    image,
                    propagated[idx],
                    "pass",
                    previous_mask=previous_mask,
                    previous_bbox=previous_bbox,
                    raw_mask=propagated[idx],
                )
            else:
                row, preview_path, mask_path = save_phase1b_outputs(
                    state,
                    idx,
                    image,
                    None,
                    "needs_review",
                    reason="sam2_missing_frame",
                )
        rows.append(normalize_review_row(row))
        if row["status"] != "no_device" and Path(mask_path).is_file():
            previous_mask = load_mask_image(Path(mask_path)).astype(bool)
            previous_bbox = mask_to_bbox(previous_mask.astype(np.uint8))
        else:
            previous_mask = None
            previous_bbox = None

    rows = [row for row in merge_review_rows([], rows) if 0 <= int(row["frame_index"]) < len(state["frame_paths"])]
    review_path = write_sequence_review(str(state["sequence_id"]), rows)
    pending = filtered_review_rows(rows, True)
    selected = pending[0] if pending else rows[0]
    selected_index = int(selected["frame_index"])
    state["frame_index"] = selected_index
    state["show_preview_overlay"] = True
    state["preview_overlay_path"] = str(selected["preview_path"])
    state["preview_mask_path"] = str(selected["device_mask_visible_path"])
    state["sam2_raw_mask_path"] = str(selected["sam2_raw_mask_path"])
    state["mask_edited"] = as_bool(selected["mask_edited"])
    state["box_points"] = []
    state["box"] = None
    state["positive_points"] = []
    state["negative_points"] = []
    state["saved_prompt"] = False
    status_counts: dict[str, int] = {}
    for row in rows:
        status = str(row["status"])
        status_counts[status] = status_counts.get(status, 0) + 1
    state["status"] = (
        f"一键自动标注完成：{len(rows)}/{len(state['frame_paths'])} 帧；"
        f"待复查 {status_counts.get('needs_review', 0)} 帧；结果已保存到 {review_path}"
    )
    return compose_outputs(state)`;
