    delta: int,
):
    return manual_frame_change(
        sequence_state,
        int(sequence_state["frame_index"]) + delta,
    )


def confirm_and_advance_manual(sequence_state: dict[str, object]):
    state = dict(sequence_state)
    frame_index = int(state["frame_index"])
    rows = read_sequence_review(str(state["sequence_id"]))
    existing = next(
        (normalize_review_row(row) for row in rows if int(row["frame_index"]) == frame_index),
        None,
    )
    if existing is None:
        state["status"] = "当前帧还没有 Mask。请先画框并点击“生成当前帧 SAM2 Mask”。"
        return compose_manual_outputs(state)
    mask_path = Path(str(existing["device_mask_visible_path"]))
    raw_path = Path(str(existing["sam2_raw_mask_path"]))
    if not mask_path.is_file() or not raw_path.is_file():
        state["status"] = "当前帧的 Mask 文件缺失，请重新生成当前帧 Mask。"
        return compose_manual_outputs(state)
    image = read_frame_image(state)
    mask = load_mask_image(mask_path, image.shape[:2])
    raw_mask = load_mask_image(raw_path, image.shape[:2])
    row, overlay_path, final_mask_path = save_phase1b_outputs(
        state,
        frame_index,
        image,
        mask,
        "pass",
        raw_mask=raw_mask,
        mask_edited=as_bool(existing["mask_edited"]),
        quality_reason=str(existing["quality_reason"] or existing["reason"]),
        manual_confirmed=True,
    )
    upsert_sequence_review(str(state["sequence_id"]), [row])
    if frame_index < len(state["frame_paths"]) - 1:
        next_outputs = on_frame_change(state, frame_index + 1)
        state = next_outputs[1]
        state["click_mode"] = "box"
        state["status"] = f"帧 {frame_index} 已确认保存。现在请框选帧 {frame_index + 1}。"
    else:
        state["show_preview_overlay"] = True
        state["preview_overlay_path"] = overlay_path
        state["preview_mask_path"] = final_mask_path
        state["sam2_raw_mask_path"] = str(row["sam2_raw_mask_path"])
        state["mask_edited"] = as_bool(row["mask_edited"])
        state["status"] = "最后一帧已确认保存，当前 5 帧手动标注完成。"
    return compose_manual_outputs(state)


def mark_no_device_and_advance_manual(sequence_state: dict[str, object]):
    base_outputs = mark_no_device(sequence_state)
    state = base_outputs[1]
    frame_index = int(state["frame_index"])
    image = read_frame_image(state)
    row, _, _ = save_phase1b_outputs(
        state,
        frame_index,
        image,
        None,
        "no_device",
        reason="marked_no_device",
    )
    upsert_sequence_review(str(state["sequence_id"]), [row])
    if frame_index < len(state["frame_paths"]) - 1:
        next_outputs = on_frame_change(state, frame_index + 1)
        state = next_outputs[1]
        state["click_mode"] = "box"
        state["status"] = f"帧 {frame_index} 已标记 no_device。现在请处理帧 {frame_index + 1}。"
    else:
        state["status"] = "最后一帧已标记 no_device，当前 5 帧手动标注完成。"
    return compose_manual_outputs(state)


